-- Fill the English fields for the existing curated content. Personal names and author lists are intentionally left unchanged.
UPDATE positions SET title_en = CASE title WHEN '副教授' THEN 'Associate Professor' WHEN '永續組組長' THEN 'Director of Sustainability Division' ELSE title END, organization_en = CASE organization WHEN '逢甲大學' THEN 'Feng Chia University' ELSE organization END, department_en = CASE department WHEN '水利工程與資源保育學系' THEN 'Department of Water Resources Engineering and Conservation' WHEN '永續處' THEN 'Office of Sustainability' ELSE department END WHERE title_en IS NULL;
UPDATE research_areas SET title_en = CASE title
  WHEN '水庫與河川泥砂運移' THEN 'Reservoir and River Sediment Transport'
  WHEN '水庫淤積與防淤排砂' THEN 'Reservoir Sedimentation and Desilting'
  WHEN '水工模型試驗' THEN 'Hydraulic Model Experiments'
  WHEN '水文、水理與泥砂數值模擬' THEN 'Numerical Modeling of Hydrology, Hydraulics, and Sediment Transport'
  WHEN '現地監測' THEN 'Field Monitoring'
  WHEN '人工智慧與影像分析' THEN 'Artificial Intelligence and Image Analysis'
  WHEN '洪水、泥砂與都市淹水預警' THEN 'Flood, Sediment, and Urban Inundation Early Warning'
  WHEN '流域數位孿生' THEN 'Watershed Digital Twin'
  WHEN '氣候韌性與防災管理' THEN 'Climate Resilience and Disaster Management'
  ELSE title END WHERE title_en IS NULL;
UPDATE labs SET description_en = 'STARLAB focuses on reservoir and river sediment transport, hydraulic model experiments, numerical modeling, field monitoring, artificial intelligence, and digital twins. The research is applied to reservoir desilting, flood and sediment early warning, urban inundation detection, and watershed decision support.' WHERE id = 1 AND description_en IS NULL;
UPDATE research_interests SET title_en = CASE title
  WHEN '水庫淤積、防淤及排砂操作' THEN 'Reservoir Sedimentation, Desilting, and Sediment Release Operations'
  WHEN '河川泥砂運移與河道沖淤' THEN 'River Sediment Transport and Channel Morphodynamics'
  WHEN '水工模型試驗與智慧量測' THEN 'Hydraulic Model Experiments and Smart Measurement'
  WHEN '數值模式與現地資料驗證' THEN 'Numerical Models and Field Data Validation'
  WHEN '人工智慧與影像辨識' THEN 'Artificial Intelligence and Image Recognition'
  WHEN '洪水、泥砂與淹水預警' THEN 'Flood, Sediment, and Inundation Early Warning'
  WHEN '流域數位孿生與決策支援' THEN 'Watershed Digital Twins and Decision Support'
  WHEN '都市防洪與氣候韌性' THEN 'Urban Flood Resilience and Climate Adaptation'
  WHEN '水利防災科普與人才培育' THEN 'Water Disaster Education and Talent Development'
  ELSE title END WHERE title_en IS NULL;
UPDATE research SET title_en = CASE title WHEN '水庫與河川水砂治理' THEN 'Reservoir and River Sediment Management' WHEN '水工模型與智慧量測' THEN 'Hydraulic Models and Smart Measurement' WHEN '人工智慧與災害預警' THEN 'Artificial Intelligence and Disaster Early Warning' WHEN '流域數位孿生' THEN 'Watershed Digital Twins' WHEN '都市防洪與氣候韌性' THEN 'Urban Flood Resilience and Climate Adaptation' ELSE title END, description_en = CASE id WHEN 1 THEN 'This research investigates reservoir sedimentation, density currents, channel morphodynamics, and sediment transport mechanisms, with a focus on sediment bypass tunnels, sediment release operations, and reservoir capacity maintenance. Methods include hydraulic model experiments, numerical modeling, field monitoring, and engineering data analysis.' WHEN 2 THEN 'Hydraulic models are used to analyze flow, sediment, local scour, and drainage performance. Image analysis, automated measurement, and real-time data processing are introduced to improve experimental data quality and engineering applications.' WHEN 3 THEN 'Machine learning, deep learning, image recognition, and Internet of Things technologies are integrated to develop sediment concentration prediction, joint flood and sediment warning, and urban inundation detection methods.' WHEN 4 THEN 'Hydrologic, hydraulic, and sediment models are integrated with field monitoring data to build watershed digital twins and decision-support tools for watershed management, disaster early warning, and water resources management.' WHEN 5 THEN 'Land-use planning, drainage planning, flood-control engineering, and climate adaptation strategies are integrated to assess urban inundation risk and develop cross-disciplinary governance methods.' ELSE description END WHERE description_en IS NULL;
UPDATE research_summaries SET text_en = CASE id WHEN 1 THEN 'From 2021 to 2026, 16 journal papers are listed, including 14 SCIE papers and 2 EI papers.' WHEN 2 THEN 'There are also 28 conference papers and one industry case-study teaching material.' WHEN 3 THEN 'Three invention patents were obtained after 2021, along with one earlier jointly developed invention patent.' WHEN 4 THEN 'Eighteen research, industry-academia, teaching, and international talent-development projects were led.' WHEN 5 THEN 'Ten projects were co-led and two projects were jointly led.' WHEN 6 THEN 'Six National Science and Technology Council undergraduate research projects were supervised.' WHEN 7 THEN 'From 2009 to 2018, 37 research and engineering projects at the NTU Hydraulic Engineering Laboratory were involved.' ELSE text END WHERE text_en IS NULL;
UPDATE other_publications SET title_en = CASE title WHEN '臺灣產業個案教材《水庫醫生》' THEN 'Taiwan Industry Case Study Teaching Material: Reservoir Doctor' ELSE title END, description_en = CASE description WHEN '佳作' THEN 'Honorable Mention' ELSE description END WHERE title_en IS NULL;
UPDATE patents SET title_en = CASE title WHEN '水質的監測方法與系統' THEN 'Water Quality Monitoring Method and System' WHEN '災害預警方法及災害預警系統' THEN 'Disaster Warning Method and Disaster Warning System' WHEN '水文資料分析方法及水文資料分析系統' THEN 'Hydrological Data Analysis Method and Hydrological Data Analysis System' WHEN '軌道式雷射光學掃描設備及方法' THEN 'Rail-Mounted Laser Optical Scanning Apparatus and Method' ELSE title END WHERE title_en IS NULL;
UPDATE projects SET title_en = CASE id WHEN 1 THEN 'Sediment Transport Decision Support System for the Tamsui River Basin Using Digital Twins' WHEN 2 THEN 'Small Water Engineer Training Program' WHEN 3 THEN 'Application and Guideline Development of Non-Destructive Deep Drainage Technology for Emergency Slope Disaster Response' WHEN 4 THEN 'Preliminary Integration of a Watershed Numerical Model and Digital Twin' WHEN 5 THEN 'Prototype Development of a Dynamic Inundation Early Warning System Using Image Analysis' WHEN 6 THEN 'Analysis of Sediment Disasters at Critical Stream-Crossing Sections and Solutions for Sediment Neutralization' WHEN 7 THEN 'Joint Early Warning and Decision Analysis System for Basin-Wide Flood and Sediment Disasters' WHEN 8 THEN 'Disaster-Prevention Road Network Survey and Structural Inspection Plan for the Nantou Branch' WHEN 9 THEN 'Assessment and Planning of the Overall Governance Strategy for the Yusui River' WHEN 10 THEN 'CDIO-Based Immersive Fluid Mechanics Teaching Through Everyday Fluid Dynamics' WHEN 11 THEN 'Fun Fluid Mechanics 2.0: Teaching Transformation after the Pandemic' WHEN 12 THEN 'Application for Environmental Education Facility Certification' WHEN 13 THEN 'Application for Environmental Education Facility Certification for Fu-Yu Umbrella' WHEN 14 THEN 'Watershed Sediment Source Analysis System Using Data Science and Machine Learning' WHEN 15 THEN 'Taiwan-Italy Sustainable Water Resources and Resilient Agricultural Disaster Prevention Internship Program' WHEN 16 THEN 'Taiwan-Thailand Sustainable Water-Energy-Food Development Internship Program' WHEN 17 THEN 'Taiwan-Japan Watershed Governance and Resilient Disaster Prevention Internship Program' WHEN 18 THEN 'Taiwan-Thailand Water-Energy-Food Nexus and Resilient Adaptation Internship Program' ELSE title END, organization_en = CASE WHEN organization LIKE '%國科會%' THEN REPLACE(REPLACE(organization, '國科會產學合作', 'NSTC Industry-Academia Cooperation'), '國科會', 'National Science and Technology Council') WHEN organization LIKE '%水利署%' THEN 'Water Resources Agency, Ministry of Economic Affairs' WHEN organization LIKE '%農村水保署%' THEN 'Rural Development and Soil and Water Conservation Agency' WHEN organization = '教育部' THEN 'Ministry of Education' WHEN organization LIKE '%教育部／%' THEN REPLACE(organization, '教育部', 'Ministry of Education') ELSE organization END, role_en = CASE role WHEN '主持人' THEN 'Principal Investigator' ELSE role END WHERE title_en IS NULL;
UPDATE collaboration_projects SET text_en = CASE id WHEN 1 THEN 'Hydraulic experiments, simulation, and risk analysis for reservoir sediment management.' WHEN 2 THEN 'Study of the ecological and morphological impacts of Shimen Reservoir flood and sediment release on the downstream river.' WHEN 3 THEN 'A smart cloud microservice early warning platform for urban hydrological changes under extreme climate.' WHEN 4 THEN 'International alliance for net-zero technology and ecological innovation.' WHEN 5 THEN 'Assessment of ESG outcomes for sustainable community spatial governance and disaster risk reduction.' WHEN 6 THEN 'Four-university alliance action for one university to safeguard one river.' ELSE text END WHERE text_en IS NULL;
UPDATE experiences SET period_en = CASE id WHEN 1 THEN 'February 2024–Present' WHEN 2 THEN 'February 2022–January 2024' WHEN 3 THEN 'February 2021–January 2022' WHEN 4 THEN 'August 2020–January 2021' WHEN 5 THEN 'June 2018–June 2020' WHEN 6 THEN 'February 2017–September 2017' WHEN 7 THEN '2009–2018' ELSE period END, organization_en = CASE organization WHEN '逢甲大學' THEN 'Feng Chia University' WHEN '國立臺北商業大學通識教育中心' THEN 'Center for General Education, National Taipei University of Business' WHEN '國立臺灣大學土木工程學系' THEN 'Department of Civil Engineering, National Taiwan University' WHEN '國立臺灣大學水工試驗所' THEN 'Hydraulic Engineering Laboratory, National Taiwan University' ELSE organization END, position_en = CASE id WHEN 1 THEN 'Associate Professor; Director of Sustainability Division' WHEN 2 THEN 'Assistant Professor' WHEN 3 THEN 'Assistant Professor' WHEN 4 THEN 'Lecturer' WHEN 5 THEN 'Postdoctoral Researcher' WHEN 6 THEN 'Visiting Scholar' WHEN 7 THEN 'Ph.D. Student and Project Staff' ELSE position END WHERE period_en IS NULL;
UPDATE research_topics SET topic_en = CASE topic WHEN '水庫與河川泥砂運移' THEN 'Reservoir and River Sediment Transport' WHEN '水工模型試驗' THEN 'Hydraulic Model Experiments' WHEN '數值模擬與模式驗證' THEN 'Numerical Modeling and Model Validation' WHEN '現地調查與智慧監測' THEN 'Field Investigation and Smart Monitoring' WHEN '人工智慧與影像分析' THEN 'Artificial Intelligence and Image Analysis' WHEN '洪水與泥砂災害預警' THEN 'Flood and Sediment Disaster Early Warning' WHEN '流域數位孿生' THEN 'Watershed Digital Twins' WHEN '水資源與氣候韌性' THEN 'Water Resources and Climate Resilience' ELSE topic END WHERE topic_en IS NULL;
UPDATE experience_items SET text_en = CASE WHEN text LIKE '%國際及國內期刊論文審查%' THEN 'Reviewing international and domestic journal manuscripts.' WHEN text LIKE '%碩博士學位考試%' THEN 'Reviewing master’s and doctoral degree examinations and doctoral qualifying examinations.' WHEN text LIKE '%教師升等%' THEN 'Reviewing faculty promotions, outstanding papers, and industry-academia technologies.' WHEN text LIKE '%學術論壇主持%' THEN 'Chairing academic forums and giving invited talks at universities in Taiwan and abroad.' WHEN text LIKE '%課程、招生%' THEN 'Serving on committees for courses, admissions, and graduate affairs.' WHEN text LIKE '%校級永續發展%' THEN 'University-level sustainability development and international exchange.' WHEN text LIKE '%流體力學與水利%' THEN 'Fluid mechanics and water resources engineering courses.' WHEN text LIKE '%環境、永續%' THEN 'Environmental, sustainability, smart city, and disaster management courses.' WHEN text LIKE '%CDIO%' THEN 'CDIO and practice-oriented teaching.' WHEN text LIKE '%水利防災科普%' THEN 'Water disaster prevention outreach education.' WHEN text LIKE '%國科會大專%' THEN 'Supervision of NSTC undergraduate research projects.' WHEN text LIKE '%國際實習%' THEN 'International internships and overseas talent development.' WHEN text LIKE '%人工智慧學校%' THEN 'Artificial Intelligence School completion certificate.' WHEN text LIKE '%EMI 教學%' THEN 'EMI teaching completion certificate.' WHEN text LIKE '%企業永續管理師%' THEN 'Corporate sustainability manager.' WHEN text LIKE '%溫室氣體盤查%' THEN 'Greenhouse gas inventory lead verifier.' WHEN text LIKE '%Python 證照%' THEN 'Python certificate.' WHEN text LIKE '%NVIDIA 證照%' THEN 'NVIDIA certificate.' ELSE text END WHERE text_en IS NULL;
UPDATE international_items SET country_en = CASE country WHEN '義大利' THEN 'Italy' WHEN '日本' THEN 'Japan' WHEN '泰國' THEN 'Thailand' WHEN '印度' THEN 'India' WHEN '澳洲' THEN 'Australia' WHEN '美國' THEN 'United States' ELSE country END, institution_en = CASE institution WHEN '義大利國家研究委員會 CNR' THEN 'National Research Council of Italy (CNR)' WHEN '日本筑波大學' THEN 'University of Tsukuba, Japan' WHEN '京都大學防災研究所' THEN 'Disaster Prevention Research Institute, Kyoto University' WHEN '泰國清邁大學及相關研究中心' THEN 'Chiang Mai University and related research centers, Thailand' WHEN '美國墾務局' THEN 'U.S. Bureau of Reclamation' ELSE institution END, description_en = CASE WHEN description LIKE '%已核定國際人才培育合作%' THEN 'Approved international talent-development cooperation.' WHEN description LIKE '%洽談、共同研議%' THEN 'The cooperation is in discussion, joint planning, or an exploratory stage.' WHEN description LIKE '%訪問研究%' THEN 'Visited University of Colorado Denver for research in 2017.' WHEN description LIKE '%數值模式及 SRH%' THEN 'Technical exchange with the U.S. Bureau of Reclamation on reservoir and river numerical modeling and SRH.' WHEN description LIKE '%臺美水利%' THEN 'Participated in research on the introduction and application of Taiwan–U.S. water resources technology.' ELSE description END WHERE description_en IS NULL;
UPDATE international_conferences SET name_en = CASE WHEN name = '水庫沉砂繞道相關國際會議' THEN 'International conferences on reservoir sediment bypass tunnels' ELSE name END, city_en = city WHERE name_en IS NULL;
UPDATE news SET category_en = CASE category WHEN '受邀演講' THEN 'Invited Talks' WHEN '國際交流' THEN 'International Exchange' WHEN '論文發表' THEN 'Publications' WHEN '計畫' THEN 'Projects' WHEN '學生與教學' THEN 'Students and Teaching' ELSE category END, title_en = CASE title WHEN '[測試] 最新論文發表消息' THEN '[Test] Latest Publication News' WHEN '[測試] 研究計畫啟動' THEN '[Test] Research Project Launched' WHEN '[測試] 學生與教學活動' THEN '[Test] Student and Teaching Activity' WHEN '[測試] 國際交流活動' THEN '[Test] International Exchange Activity' ELSE title END, content_en = CASE WHEN content LIKE '%測試%' THEN 'This is a test news item for checking the homepage and pinned-news layout.' ELSE content END WHERE title_en IS NULL;
